import 'package:flutter/material.dart';
import '../services/purchase_service.dart';
class PurchasePage extends StatefulWidget{const PurchasePage({super.key});@override State<PurchasePage> createState()=>_PurchasePageState();}
class _PurchasePageState extends State<PurchasePage>{List<Map<String,dynamic>> rows=[];bool loading=true;String search='';@override void initState(){super.initState();_load();}Future<void>_load()async{try{rows=await PurchaseService.list(search:search);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}if(mounted)setState(()=>loading=false);}
Future<void>_edit([Map<String,dynamic>? row])async{final s=TextEditingController(text:'${row?['supplier_id']??''}'),i=TextEditingController(text:'${row?['nama_item']??''}'),t=TextEditingController(text:'${row?['tonase_supplier']??''}'),d=TextEditingController(text:'${row?['tanggal_transaksi']??DateTime.now().toIso8601String().substring(0,10)}');final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:Text(row==null?'Tambah Pembelian':'Ubah Pembelian'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:s,decoration:const InputDecoration(labelText:'Kode vendor supplier')),TextField(controller:d,decoration:const InputDecoration(labelText:'Tanggal YYYY-MM-DD')),TextField(controller:i,decoration:const InputDecoration(labelText:'Nama item')),TextField(controller:t,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Tonase supplier'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Batal')),FilledButton(onPressed:()async{try{await PurchaseService.save({'supplier_id':s.text,'tanggal_transaksi':d.text,'nama_item':i.text,'tonase_supplier':double.tryParse(t.text)??0},id:row?['id']?.toString());if(context.mounted)Navigator.pop(context,true);}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}},child:const Text('Simpan'))]));if(ok==true)_load();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Pembelian')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari PO atau supplier',border:OutlineInputBorder()),onChanged:(v){search=v;_load();})),Expanded(child:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:_load,child:ListView.builder(itemCount:rows.length,itemBuilder:(_,x){final r=rows[x];return ListTile(title:Text('${r['kode_transaksi']??'-'}'),subtitle:Text('${r['nama_supplier']??r['supplier_id']??'-'} • ${r['nama_item']??'-'}\nTonase: ${r['tonase_supplier']??0}'),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='edit')_edit(r);else{await PurchaseService.remove('${r['id']}');_load();}},itemBuilder:(_)=>const[PopupMenuItem(value:'edit',child:Text('Ubah')),PopupMenuItem(value:'delete',child:Text('Hapus'))]));})))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_edit(),icon:const Icon(Icons.add),label:const Text('Tambah')));
}
